// Prepara os dados para buscar a foto na UZAPI e enviar ao CRM v2.
// No lote, le o item atual do Loop leads. No subworkflow, usa os dados recebidos na configuracao.
let lead;
try {
  lead = $('Loop leads').item.json;
} catch {
  lead = $('Configurar sincronizacao fotos').first().json;
}
const config = $('Configurar sincronizacao fotos').first().json;
const phone = String(lead.phone ?? '').replace(/\D/g, '');
const leadId = String(lead.lead_id ?? '').trim();
const username = String(config.uzapi_username ?? '').trim();
const version = String(config.uzapi_version ?? '').trim();
const phoneNumberId = String(config.uzapi_phone_number_id ?? '').trim();
const crmBaseUrl = String(config.crm_base_url ?? '').trim();
const phoneMasked = phone ? phone.replace(/^(\d{4})\d+(\d{2})$/, '$1*****$2') : '';
const valido = /^\d{10,15}$/.test(phone) && Boolean(leadId && username && version && phoneNumberId && crmBaseUrl);
return [{ json: {
  valido,
  motivo_invalido: valido ? '' : 'LEAD_TELEFONE_OU_CONFIG_INVALIDA',
  lead_id: leadId,
  phone,
  phone_masked: phoneMasked,
  uzapi_username: username,
  uzapi_version: version,
  uzapi_phone_number_id: phoneNumberId
} }];

// Item invalido volta ao loop sem chamar UZAPI ou CRM.
const lead = $('Preparar lead para foto').item.json;
return [{ json: {
  codigo: 'LEAD_IGNORADO_FOTO',
  motivo: lead.motivo_invalido,
  lead_id: lead.lead_id,
  phone_masked: lead.phone_masked,
  enviado_crm: false
} }];

// Extrai a URL real da foto retornada pela UZAPI.
// Contrato CRM v2: se nao houver URL, o caminho correto e chamar DELETE /internal/v1/leads/{leadId}/foto.
const evento = $('Preparar lead para foto').item.json;
const resposta = $('Buscar foto UZAPI').item.json ?? {};
const dadosFoto = resposta.data?.data ?? {};
const statusInterno = String(dadosFoto.status ?? resposta.data?.status ?? resposta.status ?? '').trim().toLowerCase();
const mensagemInterna = String(resposta.data?.message ?? resposta.message ?? '').trim();
const candidatos = [
  resposta.profilePictureUrl,
  dadosFoto.url,
  dadosFoto.link,
  dadosFoto.picture,
  dadosFoto.pictureUrl,
  dadosFoto.profilePictureUrl,
  dadosFoto.profilePicUrl,
  dadosFoto.imageUrl,
  dadosFoto.imgUrl,
  resposta.data?.url,
  resposta.data?.link,
  resposta.url,
  resposta.link
];
const url = String(candidatos.find((valor) => /^https?:\/\//i.test(String(valor ?? ''))) ?? '').trim();
const erroUzapi = !url && (statusInterno === 'error' || Boolean(mensagemInterna));
return [{ json: {
  ...evento,
  tem_foto: Boolean(url),
  profilePictureUrl: url,
  foto_indisponivel: !url,
  motivo_foto_indisponivel: url ? '' : (erroUzapi ? mensagemInterna : 'UZAPI_NAO_RETORNOU_URL_DE_FOTO'),
  codigo_busca_foto: url ? 'URL_FOTO_ENCONTRADA' : (erroUzapi ? 'FOTO_INDISPONIVEL_UZAPI' : 'URL_FOTO_NAO_RETORNADA_PELA_UZAPI'),
  uzapi_arquivo_nome: String(dadosFoto.filename ?? ''),
  uzapi_midia_id: String(dadosFoto.id ?? ''),
  uzapi_midia_tipo: String(dadosFoto.type ?? '')
} }];

// Confirma o resultado do DELETE do CRM v2.
// REMOVIDA e sucesso idempotente. 4xx e definitivo; 5xx deve ser repetido conforme contrato.
const evento = $('Extrair URL da foto').item.json;
const crm = $('Remover foto no CRM').item.json ?? {};
const erro = crm.error ?? {};
const status = String(crm.status ?? '').trim().toUpperCase();
const statusCode = Number(crm.statusCode ?? erro.statusCode ?? erro.httpCode ?? 0);
const sucesso = status === 'REMOVIDA';
const erroDefinitivo = statusCode >= 400 && statusCode < 500;
const erroRepetivel = statusCode >= 500;
return [{ json: {
  codigo: sucesso
    ? 'FOTO_CRM_REMOVIDA'
    : (erroRepetivel ? 'FOTO_CRM_REMOCAO_ERRO_5XX_REPETIVEL' : (erroDefinitivo ? 'FOTO_CRM_REMOCAO_ERRO_4XX_DEFINITIVO' : 'FOTO_CRM_REMOCAO_RESPOSTA_INESPERADA')),
  enviado_crm: sucesso,
  retry_recomendado: erroRepetivel,
  erro_definitivo: erroDefinitivo,
  lead_id: evento.lead_id,
  phone_masked: evento.phone_masked,
  operation: 'DELETE',
  status_crm: status,
  status_code: Number.isFinite(statusCode) ? statusCode : 0,
  motivo_origem: String(evento.motivo_foto_indisponivel ?? ''),
  erro_titulo: String(erro.title ?? erro.message ?? crm.title ?? '')
} }];

// Valida os status aceitos pelo contrato v2 do CRM.
// ATUALIZADA e INALTERADA sao sucesso; INALTERADA nao deve gerar retry.
const evento = $('Extrair URL da foto').item.json;
const crm = $('Enviar foto para CRM').item.json ?? {};
const erro = crm.error ?? {};
const status = String(crm.status ?? '').trim().toUpperCase();
const statusCode = Number(crm.statusCode ?? erro.statusCode ?? erro.httpCode ?? 0);
const sucessos = ['ATUALIZADA', 'INALTERADA'];
const sucesso = sucessos.includes(status);
const erroDefinitivo = statusCode >= 400 && statusCode < 500;
const erroRepetivel = statusCode >= 500;
return [{ json: {
  codigo: sucesso
    ? 'FOTO_CRM_SINCRONIZADA'
    : (erroRepetivel ? 'FOTO_CRM_ERRO_5XX_REPETIVEL' : (erroDefinitivo ? 'FOTO_CRM_ERRO_4XX_DEFINITIVO' : 'FOTO_CRM_RESPOSTA_INESPERADA')),
  enviado_crm: sucesso,
  retry_recomendado: erroRepetivel,
  erro_definitivo: erroDefinitivo,
  lead_id: String(crm.leadId ?? evento.lead_id ?? ''),
  phone_masked: evento.phone_masked,
  operation: 'POST',
  status_crm: status,
  status_code: Number.isFinite(statusCode) ? statusCode : 0,
  erro_titulo: String(erro.title ?? erro.message ?? crm.title ?? '')
} }];

